#include <stdio.h>

int count[1001];

int main() {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    for (int i = 0; i < n; i++) {
        int p;
        scanf("%d", &p);
        count[p]++;
    }

    long long total = 0;
    int items_seen = 0;

    for (int p = 1000; p >= 1; p--) {
        while (count[p] > 0) {
            items_seen++;
            if (items_seen % 3 != 0) {
                total += p;
            }
            count[p]--;
        }
    }

    printf("%lld\n", total);

    return 0;
}
